WITH g AS (SELECT season,h,daytype, rain>0 wet, count(*) n,avg(y) mean FROM hours WHERE functioning GROUP BY ALL), cells AS(SELECT a.season,a.h,a.daytype,a.n dry_n,b.n wet_n,a.mean dry_mean,b.mean wet_mean FROM g a JOIN g b USING(season,h,daytype) WHERE NOT a.wet AND b.wet AND a.n>=3 AND b.n>=3) SELECT count(*) cells,sum(dry_n) dry_n,sum(wet_n) wet_n,sum(dry_mean*wet_n)/sum(wet_n) matched_dry,sum(wet_mean*wet_n)/sum(wet_n) wet FROM cells;
